UPDATE fleet_tasks SET definition = json_remove(definition, '$.steps[' || (SELECT j.key FROM json_each(fleet_tasks.definition, '$.steps') j WHERE json_extract(j.value, '$.name') = 'rc-contract') || ']'), version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 'management-personas' AND EXISTS (SELECT 1 FROM json_each(fleet_tasks.definition, '$.steps') j WHERE json_extract(j.value, '$.name') = 'rc-contract'); UPDATE remediation_contracts SET status = 'superseded', verify_transport = 'd1-query', module = 'probe-template-v3-generic', attempts = 0, deferred_since = NULL, next_due_at = NULL, last_verdict = 'superseded:closure-observing-probe-at-birth (CLOSE-PROBE-CIRCULAR-1: this template observes the guarded issue status, which issue_close_evidence_required only lets change after a close that the same probe blocks; a doer that knows the defect replaces it with a probe that measures it)', precondition = 'no earlier birth template matched this issue (ORPHAN-GUARD-BIRTH-1)', action = 'VACUOUS-PROBE-V3-1: this contract measures nothing while the issue is open, so it is born superseded and never blocks the close. A doer that knows the defect replaces this probe with one that measures it.', verify_probe = 'SELECT ''closed'' AS expected, (SELECT CASE WHEN status IN (''closed'', ''resolved'') THEN ''closed'' ELSE NULL END FROM agent_issues WHERE id = ' || substr(class, 7) || ') AS observed' WHERE module = 'probe-template-v4-root-cause'; UPDATE remediation_contracts SET issue_id = (SELECT b.issue_id FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), status = (SELECT b.status FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), verify_probe = (SELECT b.verify_probe FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), verify_transport = (SELECT b.verify_transport FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), last_verdict = (SELECT b.last_verdict FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), module = (SELECT b.module FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), action = (SELECT b.action FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), precondition = (SELECT b.precondition FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), attempts = (SELECT b.attempts FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), next_due_at = (SELECT b.next_due_at FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), deferred_since = (SELECT b.deferred_since FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), expected_cadence_h = (SELECT b.expected_cadence_h FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class) WHERE module = 'probe-template-v3-generic' AND class IN (SELECT class FROM bak_20261026_rc_contract_contracts); UPDATE remediation_contracts SET next_due_at = (SELECT b.next_due_at FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class) WHERE module = 'probe-template-v3-generic' AND class IN (SELECT class FROM bak_20261026_rc_contract_contracts)
